def _links(t):
    """vals[k], left[k], right[k] for the k-th real node in level order (-1 = no child)."""
    pos, c = [], 0
    for x in t:
        if x == -1:
            pos.append(-1)
        else:
            pos.append(c)
            c += 1
    vals = [x for x in t if x != -1]
    left, right = [-1] * c, [-1] * c
    for k in range(c):
        a = 2 * k + 1
        if a < len(t):
            left[k] = pos[a]
        if a + 1 < len(t):
            right[k] = pos[a + 1]
    return vals, left, right


def farthestDistances(tree):
    vals, left, right = _links(tree)
    n = len(vals)
    if n == 0:
        return []
    adj = [[] for _ in range(n)]
    for k in range(n):
        for c in (left[k], right[k]):
            if c != -1:
                adj[k].append(c)
                adj[c].append(k)

    def bfs(src):
        dist = [-1] * n
        dist[src] = 0
        order = [src]
        for x in order:
            for y in adj[x]:
                if dist[y] == -1:
                    dist[y] = dist[x] + 1
                    order.append(y)
        return dist

    d0 = bfs(0)
    a = d0.index(max(d0))
    da = bfs(a)
    b = da.index(max(da))
    db = bfs(b)
    return [max(da[i], db[i]) for i in range(n)]
